    "starter_code": "import { test, expect } from '@playwright/test';\n\ntest.describe('Item Management CRUD', () => {\n  test('should create a new item', async ({ page }) => {\n    await page.goto('/items');\n    await page.getByRole('button', { name: 'Add New Item' }).click();\n    await page.getByLabel('Item Name').fill('New Test Item');\n    await page.getByLabel('Description').fill('This is a description for the new item.');\n    await page.getByRole('button', { name: 'Save' }).click();\n    await expect(page.getByText('New Test Item')).toBeVisible();\n  });\n\n  test('should edit an existing item', async ({ page }) => {\n    await page.goto('/items');\n    // Assume 'New Test Item' already exists from a previous step or setup.\n    // Add steps here to:\n    // 1. Locate and click on 'New Test Item' (or its associated edit button).\n    // 2. Click the 'Edit' button.\n    // 3. Fill the 'Item Name' field with 'Updated Test Item'.\n    // 4. Click the 'Save' button.\n    // 5. Assert that 'Updated Test Item' is visible.\n    // 6. Assert that 'New Test Item' is no longer visible.\n  });\n});",
